const wh = $('Receive Shopify Checkout Webhook').first();

// Decode the raw body we just verified. Parse it here and ONLY here.
let raw = '';
try {
  const bin = wh.binary && wh.binary.data;
  if (bin && bin.data) raw = Buffer.from(bin.data, 'base64').toString('utf8');
} catch (e) { /* fall through */ }
if (!raw && wh.json && wh.json.body) {
  raw = typeof wh.json.body === 'string' ? wh.json.body : JSON.stringify(wh.json.body);
}

let p = {};
let parse_error = null;
try { p = JSON.parse(raw); } catch (e) { parse_error = String(e.message || e); }

// Shopify sends shipping_address / billing_address as [] before the customer
// reaches the address step, and as an object afterwards. Normalise both.
function addr(v) { return Array.isArray(v) ? (v[0] || {}) : (v || {}); }
const sa = addr(p.shipping_address);
const ba = addr(p.billing_address);
const cu = p.customer || {};
const da = cu.default_address || {};

// Shopify sends " " (a single space) for an unset name - not null.
function clean(v) {
  if (v == null) return null;
  const s = String(v).trim();
  return s.length ? s : null;
}

// Phone can arrive in any of these. Checking only p.phone is the mistake that
// makes every checkout look like it has no phone.
const countryFromAddress = clean(sa.country_code) || clean(ba.country_code) || clean(da.country_code);

const rawPhone = p.phone || cu.phone || sa.phone || ba.phone || da.phone || null;

// Shopify hands the phone back in NATIONAL format ("03 123 456"), not E.164.
// The old version just prepended '+', which turned a Beirut national number
// into a syntactically valid JAPANESE one. It passed the regex, was
// stored, and every touch would have been delivered nowhere. So the country
// dial code has to come from the address when the number is not already
// international, and if we cannot determine it we return null and let the
// no-phone branch handle it rather than invent a recipient.
const DIAL_BY_CC = { AE:'971', SA:'966', QA:'974', KW:'965', BH:'973', OM:'968',
                     JO:'962', LB:'961', MA:'212', TN:'216', DZ:'213', EG:'20',
                     GB:'44', FR:'33', US:'1', CA:'1' };

let phone_source = 'none';
function toE164(v, cc) {
  if (!v) return null;
  let s = String(v).trim().replace(/[\s()\-\.]/g, '');

  // Reject anything that is not digits/'+' BEFORE stripping. Shopify's own test
  // payload uses '555-555-SHIP'; silently deleting the letters would turn it
  // into the plausible-looking +1555555 instead of rejecting it (M2 test 6).
  if (/[^\d+]/.test(s)) { phone_source = 'invalid_characters'; return null; }

  let intl = false;
  if (s.startsWith('+')) { intl = true; s = s.slice(1); }
  else if (s.startsWith('00')) { intl = true; s = s.slice(2); }
  s = s.replace(/\D/g, '');
  if (!s) return null;

  if (intl) {
    phone_source = 'already_international';
  } else {
    const dial = DIAL_BY_CC[String(cc || '').toUpperCase()];
    if (!dial) { phone_source = 'unresolved_no_country'; return null; }
    if (s.startsWith(dial) && s.length >= dial.length + 7) {
      phone_source = 'country_code_present_without_plus';
    } else {
      s = dial + s.replace(/^0+/, '');   // drop the national trunk prefix
      phone_source = 'prefixed_from_address_country';
    }
  }

  const out = '+' + s;
  if (!/^\+[1-9]\d{6,14}$/.test(out)) { phone_source = 'invalid_after_normalise'; return null; }
  return out;
}
const phone = toE164(rawPhone, countryFromAddress);

const items = Array.isArray(p.line_items) ? p.line_items.map(li => ({
  title: clean(li.title) || clean(li.presentment_title),
  quantity: li.quantity || 1,
  price: li.price != null ? Number(li.price) : null,
  image_url: li.image_url || (li.image && li.image.src) || null
})) : [];

return [{ json: {
  parse_error,
  checkout_token: p.token || p.checkout_token || null,
  cart_token: p.cart_token || null,
  // The checkouts webhook carries NO numeric id. `name` (#38913415086339) is
  // the reference an operator can actually search for in the Shopify admin.
  shopify_checkout_id: p.id != null ? String(p.id) : clean(p.name),
  first_name: clean(cu.first_name) || clean(sa.first_name) || clean(ba.first_name) || clean(da.first_name),
  last_name:  clean(cu.last_name)  || clean(sa.last_name)  || clean(ba.last_name)  || clean(da.last_name),
  phone,
  raw_phone: rawPhone,
  email: clean(p.email) || clean(cu.email),
  // The field is customer_locale, NOT locale. Reading p.locale silently
  // discarded the only language hint Shopify gives us.
  locale: clean(p.customer_locale) || clean(p.locale),
  cart_items: items,
  cart_total: p.total_price != null ? Number(p.total_price) : null,
  // total_price and the line-item prices are in the PRESENTMENT currency - what
  // the customer actually saw. Pairing them with p.currency (the SHOP currency)
  // stored a 734 USD cart as "734 AED", and an LBP cart as "35246000 AED".
  currency: p.presentment_currency || p.currency || null,
  shop_currency: p.currency || null,
  recovery_url: p.abandoned_checkout_url || null,
  country_from_address: countryFromAddress,
  phone_source,
  item_count: items.length
}}];

const d = $json;

// Longest prefix first - +97 would otherwise swallow +971.
const DIAL = [
  ['+971','AE','Asia/Dubai','ar'],
  ['+966','SA','Asia/Riyadh','ar'],
  ['+974','QA','Asia/Qatar','ar'],
  ['+965','KW','Asia/Kuwait','ar'],
  ['+973','BH','Asia/Bahrain','ar'],
  ['+968','OM','Asia/Muscat','ar'],
  ['+962','JO','Asia/Amman','ar'],
  ['+961','LB','Asia/Beirut','ar'],
  ['+212','MA','Africa/Casablanca','fr'],
  ['+216','TN','Africa/Tunis','fr'],
  ['+213','DZ','Africa/Algiers','fr'],
  ['+20','EG','Africa/Cairo','ar'],
  ['+44','GB','Europe/London','en'],
  ['+33','FR','Europe/Paris','fr'],
  ['+1','US','America/New_York','en']
];

const phone = d.phone || '';
let country = null, timezone = null, country_lang = null;
let timezone_source = null;
for (const [pre, cc, tz, lang] of DIAL) {
  if (phone.startsWith(pre)) { country = cc; timezone = tz; country_lang = lang; timezone_source = 'phone_prefix'; break; }
}

// Defence in depth. Previously, if the phone matched no prefix the country fell
// back to the address but the TIMEZONE stayed null - and a null timezone makes
// the send-window gate in workflow 02 default a Beirut customer to Asia/Dubai.
// Derive both from the address country using the same table.
const BY_CC = {};
for (const [pre, cc, tz, lang] of DIAL) { if (!BY_CC[cc]) BY_CC[cc] = { tz: tz, lang: lang }; }

if (!country && d.country_from_address) country = String(d.country_from_address).toUpperCase();
if (country) country = String(country).toUpperCase();

if (!timezone && country && BY_CC[country]) {
  timezone = BY_CC[country].tz;
  timezone_source = 'address_country';
  if (!country_lang) country_lang = BY_CC[country].lang;
}

const name = [d.first_name, d.last_name].filter(Boolean).join(' ');
const hasArabicScript = /[؀-ۿݐ-ݿ]/.test(name);

// customer_locale looks like 'ar', 'en-GB', 'fr-FR'
let localeLang = null;
if (d.locale) {
  const base = String(d.locale).toLowerCase().split('-')[0];
  if (['ar','en','fr'].includes(base)) localeLang = base;
}

// ORDER MATTERS, and 'en' locale is deliberately demoted.
// customer_locale reflects the storefront language the shopper browsed in. A
// single-language English store reports en-US for EVERY customer, including a
// Dubai shopper who would rather be messaged in Arabic. So a NON-English locale
// is a strong signal (they actively chose it) while 'en' is weak and loses to
// phone country. Getting this backwards makes every MENA customer English.
let language = null, language_source = null;
if (hasArabicScript)                        { language = 'ar';        language_source = 'name_script'; }
else if (localeLang && localeLang !== 'en') { language = localeLang;  language_source = 'shopify_locale'; }
else if (country_lang)                      { language = country_lang; language_source = 'phone_country'; }
else if (localeLang === 'en')               { language = 'en';        language_source = 'shopify_locale_en'; }
else                                        { language = null;        language_source = 'ambiguous'; }

// ---------------------------------------------------------------------------
// GENDER - for Arabic verb/pronoun agreement only.
//
// Ruled by Hussein 2026-08-07: arabic-master-reference.md section 5 "Gender agreement"
// applies to Case 2 outbound, so workflow 02's blanket ban on
// 2nd-person-feminine forms becomes conditional on who the customer is. That
// needs a signal, and it belongs HERE: one inference per customer, made sticky
// by case2_upsert_cart, so the register cannot change between touch 1 and 3.
//
// Deliberately HIGH-PRECISION. 'unknown' is a correct answer and routes the
// model to gender-neutral phrasing (arabic-master-reference.md prefers rephrasing over
// guessing); a WRONG guess produces visibly wrong Arabic on a real handset,
// which is worse than neutral. Anything not confidently matched goes to Haiku,
// and if Haiku is unreachable it stays 'unknown'.
// ---------------------------------------------------------------------------
function inferGender(rawFirst) {
  let raw = String(rawFirst === null || rawFirst === undefined ? '' : rawFirst).trim();
  if (!raw) return { gender: 'unknown', source: 'no_name' };

  // First token only - Arabic family names carry no reliable gender signal.
  raw = raw.split(/[\s \-_.]+/)[0];

  // Strip tashkeel and unify hamza carriers so the two spellings of Asmaa hit
  // one entry. Alef-maqsura is NOT folded into ya: that ending is itself a signal.
  const ar = raw.replace(/[ً-ْٰ]/g, '').replace(/[أإآ]/g, 'ا');
  const lat = raw.toLowerCase().replace(/[^a-z]/g, '');

  // Checked FIRST: genuinely unisex names. Forcing one of these to a gender is
  // the single most likely way to address a real person wrongly.
  const AMBIGUOUS_AR = ['نور','ايمان','امل','بيان','وعد','جهاد','صباح','سلام'];
  const AMBIGUOUS_LAT = ['nour','noor','nur','iman','eman','amal','bayan','jihad','sabah',
    'salam','sam','alex','jordan','taylor','chris','robin','jamie','morgan','casey'];
  if (AMBIGUOUS_AR.indexOf(ar) !== -1 || AMBIGUOUS_LAT.indexOf(lat) !== -1) {
    return { gender: 'unknown', source: 'unisex_name' };
  }

  // Exact lists beat the ending rules below. That ordering is load-bearing:
  // Usama, Hamza, Talha, Ubayda, Muawiya all end in ta-marbuta and are MALE,
  // and Mustafa, Yahya, Musa, Isa, Murtada all end in alef-maqsura and are
  // MALE. Ending rules alone would misgender every one of them.
  const MALE_AR = ['محمد','احمد','علي','عمر','خالد','سعيد','حسن','حسين','يوسف','ابراهيم',
    'عبدالله','عبد','فهد','سلطان','ماجد','طارق','سامي','رامي','زياد','كريم','وليد','ياسر',
    'فادي','جورج','الياس','مروان','بشار','نبيل','هاني','عادل','انور','باسل','حاتم','رائد',
    'شادي','صالح','سمير','منير','جمال','كمال','نضال','عماد','عصام','فراس','غسان','ايمن',
    'بلال','انس','سيف','فيصل','ناصر','سالم','حمد','راشد','منصور','رمزي','وسام','شربل',
    'انطوان','بيار','طوني','روي',
    'مصطفى','يحيى','موسى','عيسى','مرتضى',
    'اسامة','حمزة','طلحة','عبيدة','معاوية',
    'ضياء','علاء','بهاء','زكريا','رضا'];

  const FEMALE_AR = ['مريم','زينب','رنا','ريم','هند','ندى','سحر','شهد','رغد','رشا','دينا',
    'منال','ابتسام','احلام','اسيل','هيا','دارين','كارين','ياسمين','نسرين','شيرين','سوسن',
    'سمر','سهام','سعاد','سلوى','وداد','عبير','اماني','اروى','رولا','ربى','بتول','تالا',
    'لارا','جنان','شذى','ميس','لين','جود','ملك','رهف','بشرى','نهى','مها','منى','غادة'];

  const MALE_LAT = ['mohammed','mohamed','muhammad','mohammad','ahmed','ahmad','ali','omar',
    'umar','khaled','khalid','hassan','hasan','hussein','hussain','youssef','yousef','yusuf',
    'joseph','ibrahim','abdullah','abdallah','abdul','fahad','fahd','majed','majid','tarek',
    'tariq','tarik','sami','rami','ziad','karim','kareem','walid','yasser','yaser','fadi',
    'george','georges','elias','marwan','bashar','nabil','hani','adel','anwar','basel',
    'bassel','hatem','raed','shadi','saleh','mustafa','moustafa','yahya','moussa','musa',
    'issa','reda','zakaria','diaa','alaa','bahaa','samir','mounir','jamal','kamal','nidal',
    'imad','issam','firas','ghassan','ayman','osama','hamza','bilal','anas','saif','faisal',
    'sultan','nasser','salem','hamad','rashid','mansour','ramzi','wissam','charbel','antoine',
    'pierre','tony','roy','john','david','michael','james','robert','william','thomas',
    'daniel','paul','peter','mark','jean','luc','marc'];

  const FEMALE_LAT = ['sara','sarah','layla','laila','leila','lina','lena','mariam','maryam',
    'mary','marie','fatima','fatma','fatema','aisha','aicha','huda','hoda','salma','zeinab',
    'zainab','reem','rim','rana','nada','farah','ghada','mona','mouna','samira','nadia',
    'hala','dima','dana','hind','maya','yasmin','yasmine','jasmine','rita','joelle','carine',
    'karine','rasha','dina','manal','ahlam','asil','haya','darine','nesrine','chirine',
    'sawsan','samar','siham','souad','salwa','widad','abeer','amani','arwa','rula','ruba',
    'batoul','tala','lara','shaza','mais','leen','joud','malak','rahaf','boushra','noha',
    'maha','asma','asmaa','doaa','esraa','shaimaa','wafaa','rajaa','sanaa','ghaida',
    'najwa','lubna','zahra','zahraa','jana','emma','olivia','sophia','sophie','julie',
    'laura','anna','elena','claire'];

  if (MALE_AR.indexOf(ar) !== -1 || MALE_LAT.indexOf(lat) !== -1) {
    return { gender: 'male', source: 'name_list' };
  }
  if (FEMALE_AR.indexOf(ar) !== -1 || FEMALE_LAT.indexOf(lat) !== -1) {
    return { gender: 'female', source: 'name_list' };
  }

  // Arabic morphology, applied only AFTER the exception lists above.
  if (/[؀-ۿ]/.test(ar)) {
    if (/ة$/.test(ar))           return { gender: 'female', source: 'ta_marbuta' };
    if (/اء$/.test(ar))     return { gender: 'female', source: 'alef_hamza_ending' };
    if (/ى$/.test(ar))           return { gender: 'female', source: 'alef_maqsura' };
  }

  // No Latin ending rule: a trailing 'a' is a weak signal at best and would
  // misgender Mustafa, Musa, Zakaria and Yahya on the first cart it saw.
  return { gender: 'unknown', source: 'no_match' };
}

const g = inferGender(d.first_name);

// Haiku is asked only when the answer would actually change a message.
// Language ambiguous -> always ask (we cannot yet tell whether it will be
// Arabic). Gender unknown -> ask ONLY for Arabic carts: agreement is
// meaningless in en/fr, and a call per cart that changes nothing is a real
// bill on a client's account.
let needs_ai = false, ai_reason = null;
if (language === null) {
  needs_ai = true; ai_reason = 'language';
} else if ((language === 'ar' || language === 'mixed') && g.gender === 'unknown') {
  needs_ai = true; ai_reason = 'gender';
}

return [{ json: { ...d, country_code: country, timezone, timezone_source,
  language, language_source,
  customer_gender: g.gender, gender_source: g.source,
  needs_ai, ai_reason, customer_name: name || null } }];

const base = $('Detect Language And Timezone').first().json;
let language = base.language;
let source = base.language_source;
let gender = base.customer_gender || 'unknown';
let gender_source = base.gender_source || null;

if (base.needs_ai) {
  try {
    const ai = $('Classify Language With Haiku').first().json;
    const text = ai && ai.content && ai.content[0] && ai.content[0].text;

    // The prompt asks for JSON, but a model that wraps it in prose or a code
    // fence must not cost us the whole answer - take the first {...} block.
    let parsed = null;
    if (text) {
      const m = String(text).match(/\{[\s\S]*\}/);
      if (m) { try { parsed = JSON.parse(m[0]); } catch (e) { parsed = null; } }
    }

    // LANGUAGE: applied only when the heuristic chain had NO answer. Haiku is a
    // fallback, not a second opinion - a resolved heuristic always wins, which
    // matters now that needs_ai can be true for gender reasons alone.
    if (base.language === null) {
      let guess = null;
      if (parsed) guess = String(parsed.language || '').trim().toLowerCase().slice(0, 2);
      // Tolerate the pre-2026-08-07 bare-token reply shape ('ar').
      if (!guess && text) guess = String(text).trim().toLowerCase().slice(0, 2);
      if (['ar','en','fr'].includes(guess)) { language = guess; source = 'haiku'; }
    }

    // GENDER: applied only when the heuristic said unknown. 'unknown' from the
    // model is kept as unknown - it is a real answer, not a failure.
    if (gender === 'unknown' && parsed) {
      const gg = String(parsed.gender || '').trim().toLowerCase();
      if (['female','male'].includes(gg)) { gender = gg; gender_source = 'haiku'; }
    }
  } catch (e) {
    // Haiku unreachable - keep both heuristic answers. Silence over a guess.
  }
}

// Last resort. English is the safest neutral default for an unknown MENA
// customer: wrong-language Arabic reads worse than neutral English.
if (!language) { language = 'en'; source = 'default_fallback'; }

// 'unknown' is a first-class value all the way to the database: workflow 02
// reads it and tells the model to use gender-neutral phrasing rather than pick.
if (!gender) { gender = 'unknown'; gender_source = gender_source || 'no_match'; }

return [{ json: { ...base, language, language_source: source,
  customer_gender: gender, gender_source } }];
